import React from 'react';
import { Dropdown } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import classNames from 'classnames';

// hooks
import { useToggle } from '../../hooks/';

// types
import { ProfileMenu } from '../../layouts/types';
import { baseURL } from '../../api/ApiConfig';
import k3Avatar from '../../assets/images/k3Icon.png';
import noProfile from '../../assets/images/noprofile_images.jpg';

type ProfileDropdownProps = {
    userImage: string | boolean;
    username: string;
    staffname: string;
    menuItems: ProfileMenu[];
};

const ProfileDropdown = ({ userImage, username, menuItems, staffname }: ProfileDropdownProps) => {
    const [isOpen, show, hide] = useToggle();

    /*
     * toggle apps-dropdown
     */
    const toggleDropdown = () => {
        isOpen ? hide() : show();
    };

    const handleLogout = () => {
        // sessionStorage.clear();
        localStorage.clear();
        console.log('logout');
    };

    return (
        <Dropdown show={isOpen} onToggle={toggleDropdown}>
            <Dropdown.Toggle
                as="a"
                variant=""
                className="nav-link nav-user me-0 waves-effect waves-light"
                id="page-header-user-dropdown"
                onClick={toggleDropdown}>
                <img
                    src={userImage ? `${baseURL}${userImage}` : k3Avatar}
                    alt="staffProfile"
                    className="rounded-circle"
                    crossOrigin="anonymous"
                    onError={(e: any) => {
                        e.target.onerror = null;
                        e.target.src = k3Avatar;
                    }}
                    style={{ objectFit: 'cover' }}
                />
                <span className="pro-user-name ms-1">
                    {staffname}
                    <i className="mdi mdi-chevron-down"></i>
                </span>
            </Dropdown.Toggle>

            <Dropdown.Menu align="end" className="profile-dropdown">
                <div onClick={toggleDropdown}>
                    <Dropdown.Header className="noti-title">
                        <h6 className="text-overflow m-0">{`Welcome Back ${username} !`}</h6>
                    </Dropdown.Header>

                    {(menuItems || []).map((menu, i) => {
                        return (
                            <React.Fragment key={i + '-menu'}>
                                {i === menuItems.length - 1 && <Dropdown.Divider as="div" />}
                                <Link
                                    to={menu.redirectTo}
                                    className="dropdown-item notify-item"
                                    key={i + '-profile-menu'}
                                    onClick={() => {
                                        if (menu.label == 'Logout') handleLogout();
                                    }}>
                                    <i className={classNames(menu.icon, 'me-1')}></i>
                                    <span>{menu.label}</span>
                                </Link>
                            </React.Fragment>
                        );
                    })}
                </div>
            </Dropdown.Menu>
        </Dropdown>
    );
};

export default ProfileDropdown;
