import { useEffect, useState } from 'react';
import { Badge, Dropdown, Spinner } from 'react-bootstrap';
import { Link, useNavigate } from 'react-router-dom';
import classNames from 'classnames';
import { useRedux, useToggle } from '../../hooks';
import Scrollbar from '../Scrollbar';
import { getNotificationRequest, getVehicleRequest, resetGetVehicle, resetGetNotification } from '../../redux/actions';
import moment from 'moment';

const Notification = () => {
    const { dispatch, appSelector } = useRedux();
    const [notifications, setNotifications] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isOpen, show, hide] = useToggle();
    const navigate = useNavigate();

    const {
        getStaffLeaveSuccess,
        getStaffLeaveFailure,
        getClaimSuccess,
        getPermissionSuccess,
        getPermissionFailure,
        // getPetrolAllowanceSuccess,
        // getPetrolAllowanceFailure,
        getClaimFailure,
        getNotificationSuccess,
        getNotificationList,
        getNotificationFailure,
    } = appSelector((state) => ({
        getNotificationSuccess: state.notificationReducer.getNotificationSuccess,
        getNotificationList: state.notificationReducer.getNotificationList,
        getNotificationFailure: state.notificationReducer.getNotificationFailure,

        getClaimSuccess: state.claimReducer.getClaimSuccess,
        getClaimFailure: state.claimReducer.getClaimFailure,

        getPermissionSuccess: state.permissionReducer.getPermissionSuccess,
        getPermissionFailure: state.permissionReducer.getPermissionFailure,

        getStaffLeaveSuccess: state.staffLeaveReducer.getStaffLeaveSuccess,
        getStaffLeaveFailure: state.staffLeaveReducer.getStaffLeaveFailure,

        // getPetrolAllowanceSuccess: state.petrolAllowanceReducer.getPetrolAllowanceSuccess,
        // getPetrolAllowanceFailure: state.petrolAllowanceReducer.getPetrolAllowanceFailure,
    }));

    useEffect(() => {
        setIsLoading(true);
        dispatch(getNotificationRequest());
    }, [
        // getPetrolAllowanceSuccess,
        // getPetrolAllowanceFailure,
        getClaimSuccess,
        getClaimFailure,
        getPermissionSuccess,
        getPermissionFailure,
        getStaffLeaveSuccess,
        getStaffLeaveFailure,
    ]);

    useEffect(() => {
        if (getNotificationSuccess) {
            setIsLoading(false);
            setNotifications(getNotificationList || []);
            dispatch(resetGetNotification());
        } else if (getNotificationFailure) {
            setIsLoading(false);
            setNotifications([]);
            dispatch(resetGetNotification());
        }
    }, [getNotificationSuccess, getNotificationFailure]);

    const toggleDropdown = () => {
        isOpen ? hide() : show();
    };

    const handleNotificationClick = (route) => {
        navigate(route);
        hide();
    };

    // Get notification icon based on type
    const getNotificationIcon = (type) => {
        switch (type) {
            case 'permission':
                return 'fe-umbrella';
            case 'leave':
                return 'fe-home';
            case 'petrol':
                return 'fe-droplet';
            case 'claim':
                return 'fe-gift';
            default:
                return 'fe-bell';
        }
    };

    // Get notification badge color based on type
    const getNotificationBadge = (type) => {
        switch (type) {
            case 'permission':
                return 'primary';
            case 'leave':
                return 'danger';
            case 'petrol':
                return 'warning';
            case 'claim':
                return 'success';
            default:
                return 'info';
        }
    };

    return (
        <Dropdown show={isOpen} onToggle={isOpen ? hide : show}>
            <Dropdown.Toggle variant="" as="a" className="nav-link waves-effect waves-light" onClick={show}>
                <i className="fe-bell noti-icon" style={{ color: '#092e4b' }}></i>
                {notifications.length > 0 && (
                    <Badge bg="danger" className="rounded-circle noti-icon-badge">
                        {notifications.length}
                    </Badge>
                )}
            </Dropdown.Toggle>

            <Dropdown.Menu align="end" className="dropdown-lg">
                <div onClick={hide}>
                    <Dropdown.Item as="div" className="noti-title" style={{ background: '#26378d' }}>
                        <h5 className="m-0 text-center text-white">Staff Notifications</h5>
                    </Dropdown.Item>

                    {/* <Scrollbar className="noti-scroll">
                        {isLoading ? (
                            <div className="bg-light opacity-0.25">
                                <div className="d-flex justify-content-center m-5">
                                    <Spinner className="mt-5 mb-5" animation="border" />
                                </div>
                            </div>
                        ) : notifications.length > 0 ? (
                            notifications.map((notify, index) => (
                                <Dropdown.Item
                                    key={index.toString()}
                                    className="notify-item"
                                    onClick={() =>
                                        navigate('../../master/notification', {
                                            state: { notificationId: notify.notificationId },
                                        })
                                    }>
                                    <div className={classNames('notify-icon', 'bg-warning')}>
                                        <i className="fe-truck"></i>
                                    </div>
                                    <p className="notify-details">
                                        <strong>{notify.notificationNumber}</strong> -{' '}
                                        <span className="text-danger">
                                            Insurance Expiry: {moment(notify.notificationInsuranceTo).format('DD-MM-YYYY')}
                                        </span>
                                        <span className="text-warning">
                                            FC Expiry: {moment(notify.notificationFcTo).format('DD-MM-YYYY')}
                                        </span>
                                    </p>
                                </Dropdown.Item>
                            ))
                        ) : (
                            <div className="text-center p-3">No Expired Insurance Notifications</div>
                        )}
                    </Scrollbar> */}

                    <Scrollbar className="noti-scroll">
                        {notifications.length > 0 ? (
                            (notifications || []).map((item, index) => {
                                return (
                                    <Dropdown.Item
                                        key={index.toString()}
                                        className="notify-item"
                                        onClick={() => handleNotificationClick(item.route)}>
                                        <div
                                            className={classNames(
                                                'notify-icon',
                                                `bg-${getNotificationBadge(item.type)}`
                                            )}>
                                            <i className={getNotificationIcon(item.type)}></i>
                                        </div>
                                        <p className="notify-details">
                                            {item.text}
                                            <small className="text-muted">{item.subText}</small>
                                        </p>
                                    </Dropdown.Item>
                                );
                            })
                        ) : (
                            <div className="text-center p-3">No Staff Notifications</div>
                        )}
                    </Scrollbar>
                </div>
            </Dropdown.Menu>
        </Dropdown>
    );
};

export default Notification;
